contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address payable attacker, uint amount) public payable {
        require(msg.sender != address(c), "test must not be owner");
        require(address(this).balance >= amount, "insufficient balance");

        uint beforeBal = address(c).balance;
        uint beforeCount = c.depositsCount();

        bool fallbackReverted = false;
        try c.call{value: amount}() {
        } catch {
            fallbackReverted = true;
        }

        bool withdrawReverted = false;
        try c.withdrawAll() {
            withdrawReverted = true;
        } catch {
        }

        bool sendReverted = false;
        try c.sendMoney(attacker, amount, "") {
            sendReverted = true;
        } catch {
        }

        assert(
            !fallbackReverted &&
            c.depositsCount() == beforeCount + 1 &&
            address(c).balance == beforeBal + amount &&
            withdrawReverted &&
            sendReverted
        );
    }

    receive() external payable {}
}

